The full diff is available in the checked-out PR branch. Use `git diff` or CodeGraph for focused source navigation instead of relying only on this file.

```diff
diff --git a/instructions/pr_rework/output_rules.md b/instructions/pr_rework/output_rules.md
index f8a50d54..663a2e17 100644
--- a/instructions/pr_rework/output_rules.md
+++ b/instructions/pr_rework/output_rules.md
@@ -46,5 +46,7 @@ belong to the refinement agents). Every open thread needs a code fix in this pas
 you genuinely cannot get past, change no thread state and write the reason in `outputs/response.md`
 (start the file with `BLOCKED:` followed by what blocks you and what is needed). A pass with open
 threads and no code change is treated as blocked: threads are not resolved and the ticket moves to
-the Blocked status.
+the Blocked status. Even when blocked or awaiting a human decision, ALWAYS write
+`outputs/response.md` — it is posted as the PR comment; nothing in the run log reaches the human
+otherwise.

diff --git a/js/pushReworkChanges.js b/js/pushReworkChanges.js
index 440e8e13..1e57e6d9 100644
--- a/js/pushReworkChanges.js
+++ b/js/pushReworkChanges.js
@@ -575,6 +575,19 @@ function threadKeySet(threads) {
     return keys;
 }

+/**
+ * gh-1061 AC3: an open thread that can NEVER receive a targeted reply —
+ * threadKeyOf() is null (no threadId AND no rootCommentId). These are the
+ * machine-notice shapes (red-head markers, rework-consume payloads, prior
+ * blocked comments): review_replies.json addresses threads by id, so a null-id
+ * thread sits in the gh-957 coverage-gate denominator forever and the gate can
+ * never pass (live: dmtools-dart PR #420 / gh-395 blocked-looping for a week).
+ * Excluded from the gate denominator; reported as informational context only.
+ */
+function isUnaddressableThread(t) {
+    return !!t && threadKeyOf(t) === null;
+}
+
 /**
  * Human-readable thread identification for logs and completion comments:
  * id, file:line location, and the first body line (the reviewer's title).
@@ -589,6 +602,25 @@ function threadLabel(t) {
     return id + (loc ? ' (' + loc + ')' : '') + (body ? ' — "' + body + '"' : '');
 }

+/**
+ * gh-1061 AC2: compact one-line thread label for the blocked-comment fold —
+ * id plus a short body snippet, hard-capped at maxLen so a 39-thread
+ * enumeration stays inside the ~2000-char comment budget (threadLabel's
